#include "ksSysExDumpTask.h"
#include <array>
#include <cstdint>
#include <iostream>
#include <stdexcept>
#include <vector>
using T=ks::SysExDumpTask;using S=T::Stage;using C=T::Child;using K=T::Kind;
void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}struct Packet{unsigned type,slot,bank,program,count;uint32_t source;bool operator==(const Packet&p)const{return type==p.type&&slot==p.slot&&bank==p.bank&&program==p.program&&count==p.count&&source==p.source;}};
int main(){try{uint64_t cases=0;auto verify=[&](unsigned kind,unsigned selection,unsigned slot,unsigned initialProgram,unsigned mode){T t{K(kind),uint16_t(selection),uint8_t(slot)};std::array<uint8_t,12>header{};unsigned serial=0,headers=0,snapshots=0,flush=0;std::vector<Packet>sent;std::vector<std::array<unsigned,3>>banks;unsigned guard=0;while(!t.complete()&&!t.handoff()){check(++guard<20000,"SysEx dump pure stalled");if(t.awaitingChild()){auto c=t.child();if(c==C::Header){header.fill(0);header[11]=uint8_t(initialProgram);}if(c==C::SendHeader)++headers;if(c==C::SnapshotPatch||c==C::SnapshotMulti)++snapshots;if(c==C::Flush)++flush;if(c==C::Serial){check(t.byte()==247,"Wrong SysEx terminator");++serial;}if(c==C::Send)sent.push_back({header[6],header[7],header[10],header[11],t.count(),t.source()});if(c==C::Large)banks.push_back({0,t.bank(),t.slot()});if(c==C::Small)banks.push_back({1,t.bank(),t.slot()});if(c==C::Performance)banks.push_back({2,t.program(),t.slot()});if(c==C::Index)check(t.resumeIndex(uint16_t(selection*257+slot)),"Dump indexreply");else if(c==C::Resolve){header.fill(0);header[7]=uint8_t(slot);header[10]=uint8_t(selection>>8);header[11]=uint8_t(selection);check(t.resumeResolve(0xfffff123u+selection*256),"Dump resolvereply");}else check(t.resumeChild(),"Dump voidreply");continue;}auto read=[&](S s)->unsigned{if(s==S::SelectReadMode)return mode;if(s==S::LargeReadBank||s==S::SmallReadBank||s==S::PerformanceReadBank)return header[10];return header[11];};auto write=[&](S s,uint32_t v){unsigned at=0;switch(s){case S::PatchPublishType:case S::MultiPublishType:case S::LargePublishType:case S::SmallPublishType:case S::PerformancePublishType:case S::GlobalPublishType:case S::SinglePublishType:at=6;break;case S::LargePublishSlot:case S::SmallPublishSlot:case S::PerformancePublishSlot:case S::ResolvePublishSlot:at=7;break;case S::LargePublishBank:case S::SmallPublishBank:case S::PerformancePublishBank:case S::ResolvePublishBank:at=10;break;default:at=11;break;}header[at]=uint8_t(v);};auto stage=t.stage();auto cost=t.nextClocks(3);check(cost&&t.advanceBefore(cost-1,read,write,[](S){return 3u;})==0&&stage==t.stage(),"Early dump deadline");check(t.advanceBefore(cost,read,write,[](S){return 3u;})==cost,"Dump deadline");}
unsigned low=uint8_t(selection),high=uint8_t(selection>>8);std::vector<Packet>expected;auto one=[&](unsigned type,unsigned bank,unsigned program,unsigned count,uint32_t source,unsigned slotValue){expected.push_back({type,slotValue,bank,program,count,source});};if(kind==0||kind==1||kind==6){one(kind==0?0:kind==1?2:4,0,initialProgram,kind==1?1024:256,kind==0?0x168fc:kind==1?0x169fc:0x81ff00,0);check(snapshots==(kind==6?0u:1u),"Dump snapshot requests");}else if(kind==2||kind==3){uint32_t source=(kind==2?0x820000u:0x839000u)+uint8_t(low-(kind==2?1:5))*(kind==2?0x6400u:0x3200u);unsigned program=uint8_t(initialProgram);do{one(1,low,program,256,source,high);source+=256;program=uint8_t(program+1);}while(program<(kind==2?100u:50u));}else if(kind==4){uint32_t source=0x845800u+low*1024;for(unsigned i=0;i<50;++i)one(3,1,uint8_t(low+i),1024,source+i*1024,high);}else if(kind==5){check(banks.size()==10,"DumpAll childcount");for(unsigned i=0;i<8;++i)check(banks[i]==std::array<unsigned,3>{i<4?0u:1u,i+1,1},"DumpAll bank order");check(banks[8]==std::array<unsigned,3>{2,0,1}&&banks[9]==std::array<unsigned,3>{2,50,1},"DumpAll performance ranges");}else if(kind==7){one(1,high,low,256,0xfffff123u+selection*256,slot);check(t.handoff(),"Single dump terminator tail");}else if(kind==8){check(header[7]==slot&&header[10]==high&&header[11]==low,"Dump resolved requestmetadata");check(t.source()==0x820000u+uint16_t(selection*257+slot)*256u,"Dump unsigned index arithmetic");}else{check(flush==1,"Dump selector flush");if(low>=1&&low<=4)check(banks==std::vector<std::array<unsigned,3>>{{0,low,0}},"Select large");if(low>=5&&low<=8)check(banks==std::vector<std::array<unsigned,3>>{{1,low,0}},"Select small");if(low==9||low==10)check(banks==std::vector<std::array<unsigned,3>>{{2,low==9?0u:50u,0}},"Select performance");}
if(sent!=expected){std::cerr<<"kind="<<kind<<" selection="<<selection<<" program="<<initialProgram<<" count="<<sent.size()<<" expected="<<expected.size()<<"\n";if(!sent.empty()&&!expected.empty())std::cerr<<sent[0].type<<"/"<<sent[0].slot<<"/"<<sent[0].bank<<"/"<<sent[0].program<<"/"<<sent[0].count<<"/"<<sent[0].source<<" expected "<<expected[0].type<<"/"<<expected[0].slot<<"/"<<expected[0].bank<<"/"<<expected[0].program<<"/"<<expected[0].count<<"/"<<expected[0].source<<"\n";}check(sent==expected,"Dump packet source/metadata/count order");if(kind<=4||kind==6)check(headers==sent.size()&&serial==sent.size(),"Dump envelope count");++cases;};for(unsigned kind=0;kind<10;++kind)for(unsigned selection=0;selection<256;++selection)for(unsigned high:{0u,1u,127u,255u})for(unsigned program:{0u,49u,99u,255u})verify(kind,selection+high*256,selection,program,selection&1);std::cout<<"PASS: "<<cases<<" pure SysEx dump/request tasks; independent unsigned bank/index address, header metadata, loop/packet/envelope, selection and early-deadline oracles\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
